 1	// RUN: %testDafnyForEachResolver "%s"
 2	
 3	
 4	class Node<T> {
 5	  ghost var List: seq<T>
 6	  ghost var Repr: set<Node<T>>
 7	
 8	  var data: T
 9	  var next: Node?<T>
10	
11	  ghost predicate Valid()
12	    reads this, Repr
13	  {
14	    this in Repr &&
15	    (next == null ==> List == [data]) &&
16	    (next != null ==>
17	        next in Repr && next.Repr <= Repr &&
18	        this !in next.Repr &&
19	        List == [data] + next.List &&
20	        next.Valid())
21	  }
22	
23	  constructor (d: T)
24	    ensures Valid() && fresh(Repr)
25	    ensures List == [d]
26	  {
27	    data, next := d, null;
28	    List, Repr := [d], {this};
29	  }
30	
31	  constructor InitAsPredecessor(d: T, succ: Node<T>)
32	    requires succ.Valid()
33	    ensures Valid() && fresh(Repr - succ.Repr)
34	    ensures List == [d] + succ.List
35	  {
36	    data, next := d, succ;
37	    List := [d] + succ.List;
38	    Repr := {this} + succ.Repr;
39	  }
40	
41	  method Prepend(d: T) returns (r: Node<T>)
42	    requires Valid()
43	    ensures r.Valid() && fresh(r.Repr - old(Repr))
44	    ensures r.List == [d] + List
45	  {
46	    r := new Node.InitAsPredecessor(d, this);
47	  }
48	
49	  method SkipHead() returns (r: Node?<T>)
50	    ensures r == null ==> |List| == 1
51	    ensures r != null ==> r.Valid() && r.List == List[1..] && r.Repr <= Repr
52	  {
53	    r := next;
54	  }
55	
56	  method ReverseInPlace() returns (reverse: Node<T>)
57	    requires Valid()
58	    modifies Repr
59	    ensures reverse.Valid() && reverse.Repr <= old(Repr)
60	    ensures |reverse.List| == |old(List)|
61	    ensures forall i :: 0 <= i < |reverse.List| ==> reverse.List[i] == old(List)[|old(List)|-1-i]
62	  {
63	    var current := next;
64	    reverse := this;
65	    reverse.next := null;
66	    reverse.Repr := {reverse};
67	    reverse.List := [data];
68	
69	    while current != null
70	      invariant reverse.Valid() && reverse.Repr <= old(Repr)
71	      invariant current == null ==> |old(List)| == |reverse.List|
72	      invariant current != null ==>
73	        current.Valid() &&
74	        current in old(Repr) && current.Repr <= old(Repr) &&
75	        current.Repr !! reverse.Repr
76	      invariant current != null ==>
77	        |old(List)| == |reverse.List| + |current.List| &&
78	        current.List == old(List)[|reverse.List|..]
79	      invariant forall i :: 0 <= i < |reverse.List| ==> reverse.List[i] == old(List)[|reverse.List|-1-i]
80	      decreases if current != null then |current.List| else -1
81	    {
82	      var nx := current.next;
83	
84	      // ..., reverse, current, nx, ...
85	      current.next := reverse;
86	      current.Repr := {current} + reverse.Repr;
87	      current.List := [current.data] + reverse.List;
88	
89	      reverse := current;
90	      current := nx;
91	    }
92	  }
93	}
94

